    62|function cors(response: Response): Response {
    63|  const headers = new Headers(response.headers);
    64|  headers.set("Access-Control-Allow-Origin", "*");
    65|  headers.set("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
    66|  headers.set("Access-Control-Allow-Headers", "Content-Type,Authorization,Origin,Referer,X-Requested-With,X-Admin-Key");
    67|  headers.set("Access-Control-Max-Age", "86400");
    68|  return new Response(response.body, { status: response.status, headers });
    69|}
    70|
    71|function json(data: unknown, status = 200): Response {
    72|  return cors(new Response(JSON.stringify(data), {
    73|    status,
    74|    headers: { "Content-Type": "application/json" },
    75|  }));
