    78|function extractToken(request: Request): string {
    79|  return (request.headers.get("Authorization") || "").replace("Bearer ", "");
    80|}
    81|
    82|function generateToken(): string {
    83|  return crypto.randomUUID().replace(/-/g, "") + crypto.randomUUID().replace(/-/g, "").slice(0, 16);
    84|}
