   144|.btn-remove{width:28px;height:28px;background:#FEE2E2;border:1px solid rgba(239,68,68,.2);border-radius:var(--radius-xs);color:var(--alert);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .2s;flex-shrink:0}
   145|.btn-remove:hover{background:rgba(239,68,68,.12)}
   146|
   147|/* ── Tables ── */
   148|.table-wrap{overflow-x:auto;border-radius:var(--radius-sm);border:1px solid var(--hair)}
   149|table{width:100%;border-collapse:collapse}
   150|th{text-align:left;padding:9px 12px;font-size:10px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.3px;border-bottom:2px solid var(--hair);font-weight:600;background:var(--muted)}
   151|td{padding:9px 12px;border-bottom:1px solid var(--hair);font-size:12px}tr:hover td{background:var(--muted)}
   152|.empty-state{text-align:center;padding:28px 20px;color:var(--ink-soft)}
   153|.empty-state svg{width:40px;height:40px;color:var(--ink-faint);margin-bottom:8px}
   154|
   155|/* ── Badges ── */
   156|.badge{display:inline-flex;align-items:center;gap:5px;padding:3px 10px;border-radius:50px;font-size:10px;font-weight:600}
   157|.badge::before{content:'';width:6px;height:6px;border-radius:50%}
   158|.badge.green{background:rgba(16,185,129,.13);color:#166534}.badge.green::before{background:var(--good)}
   159|.badge.amber{background:rgba(245,158,11,.13);color:#92400E}.badge.amber::before{background:var(--watch)}
   160|.badge.gray{background:var(--muted);color:var(--ink-soft)}.badge.gray::before{background:var(--ink-faint)}
   161|.badge.red{background:rgba(239,68,68,.13);color:#991B1B}.badge.red::before{background:var(--alert)}
   162|.badge.blue{background:var(--blue-soft);color:var(--blue-d)}.badge.blue::before{background:var(--blue)}
   163|
   164|/* ── Doctor rows ── */
   165|.doc-row{display:grid;grid-template-columns:1.2fr 1fr 1.2fr 1fr 32px;gap:10px;align-items:end;padding:10px 12px;background:var(--canvas);border:1px solid var(--hair);border-radius:var(--radius-sm);margin-bottom:8px}
   166|.doc-row .form-group{margin:0}
   167|.doc-row .form-group label{font-size:10px;margin-bottom:3px}
   168|.doc-row .form-group input{padding:8px 10px;font-size:12px}
   169|.doc-row-header{display:grid;grid-template-columns:1.2fr 1fr 1.2fr 1fr 32px;gap:10px;font-size:10px;font-weight:600;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.3px;margin-bottom:6px;padding:0 12px}
   170|
   171|/* ── Misc ── */
   172|.tab-content{display:none}.tab-content.active{display:block}
   173|.guide-mono{font-family:'SF Mono',Consolas,monospace;font-size:11px}
   174|.guide-tag{color:var(--blue)}.guide-tag-opt{color:var(--ink-soft)}
   175|.flow-list{padding-left:20px;color:var(--ink-soft);line-height:1.8;font-size:12px}
   176|.flow-list b{color:var(--ink)}
   177|.loading{text-align:center;padding:32px;color:var(--ink-soft)}
   178|.spinner{display:inline-block;width:24px;height:24px;border:3px solid var(--hair);border-top-color:var(--orange);border-radius:50%;animation:spin .8s linear infinite}
   179|@keyframes spin{to{transform:rotate(360deg)}}
   180|.results-table{max-height:380px;overflow-y:auto;border-radius:var(--radius-sm)}
   181|.import-toolbar{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap;align-items:center}
   182|.import-toolbar .hint{color:var(--ink-faint);font-size:12px}
   183|.search-row{display:flex;gap:10px;margin-bottom:14px;align-items:center;flex-wrap:wrap}
   184|.search-row input{flex:1;min-width:200px;padding:9px 12px;border:1.5px solid var(--hair);border-radius:var(--radius-sm);font-size:13px;outline:none;font-family:inherit;transition:border .2s,box-shadow .2s}
   185|.search-row input:focus{border-color:var(--orange);box-shadow:0 0 0 3px var(--orange-soft)}
   186|.helper-text{font-size:11px;color:var(--ink-soft);margin-bottom:12px;line-height:1.5}
   187|.helper-text b{color:var(--ink)}
   188|
   189|@media(max-width:900px){.login-wrap{grid-template-columns:1fr}.login-brand{display:none}.login-form{padding:20px 16px;min-height:100vh}}
   190|@media(max-width:768px){
