   193|  .sidebar.collapsed{width:var(--sidebar)}
   194|  .main{margin-left:0;padding:14px}
   195|  .sidebar.collapsed~.main{margin-left:0}
   196|  .doc-row,.doc-row-header{grid-template-columns:1fr 1fr;gap:8px}
   197|  .doc-row .btn-remove,.doc-row-header span:last-child{grid-column:span 2}
